  "criteria": {
    "definition": {
      "assessment": "sufficient",
      "reason": "动机、依赖图、请求与执行身份、输入快照、输出及状态边界均明确。已确认 token 长度 n 与全层 KV 边界 k 分开，分块 prefill、采样和下一代输入之间的一步偏移解释正确；保守实现的适用范围明确。",
      "evidence": [
        {
          "path": "knowledge/algorithms/async-scheduling.md",
          "quote": "请求保存已确认 token 序列 x[0:n)、全层有效 KV 连续边界 k、采样/RNG 状态、生成计数与停止原因，满足 0≤k≤n。"
        },
        {
          "path": "knowledge/algorithms/async-scheduling.md",
          "quote": "采样成功后，将 token 放到原位置 n，再令 n 增一；它自己的 KV 仍未计算，因此 k 保持旧 n。下一代才以这个已知 token 为输入。"
        }
      ]
    },
    "legality": {
      "assessment": "sufficient",
      "reason": "取得空槽与持槽提交的合法条件已经分开；生产完成、消费可见和最后使用结束分别约束状态。统一槽的取消组合轨迹等待 CPU、传输、图及合并访问结束，旧身份丢弃不再被当作物理访问保护。原 LEG-001 已关闭。",
      "evidence": [
        {
          "path": "knowledge/algorithms/async-scheduling.md",
          "quote": "L5b READY 提交：owner[s]=(r,g)、slot_epoch[s]=epoch，本代准备完成、快照冻结且仍有提交权。"
        },
        {
          "path": "knowledge/algorithms/async-scheduling.md",
          "quote": "若 CPU c 到 t4 之后仍在读旧输入、写旧共享输出或使用旧 workspace，这条轨迹不合法，t3 必须后移。"
        },
        {
          "path": "knowledge/algorithms/async-scheduling.md",
          "quote": "使用者必须先登记，再启动；同一责任只能由自己的真实结束事件撤销。"
        }
      ]
    },
    "algorithm": {
      "assessment": "sufficient",
      "reason": "已沿 ARRIVE、取得槽与预留、准备、READY 提交、完成、消费、释放及后继建立检查闭环。active、责任集合和提交账初始化齐全；取消标志独立于物理阶段，未提交取消不扣 inflight，消费者身份与一次业务事务防止重复推进。逐层模型契约有明确链接委托，并要求完成证据覆盖全层。原 ALG-001、ALG-002、ALG-003 的具体阻塞已修复。",
      "evidence": [
        {
          "path": "knowledge/algorithms/async-scheduling.md",
          "quote": "成功后设置 owner、slot、epoch，phase=PREPARING"
        },
        {
          "path": "knowledge/algorithms/async-scheduling.md",
          "quote": "对尚未释放的当前代设置 canceled=true，不改写其在途物理阶段"
        },
        {
          "path": "knowledge/algorithms/async-scheduling.md",
          "quote": "旧代、未知或已经结束的 cid 不再改变任何请求状态或计数"
        },
        {
          "path": "knowledge/algorithms/async-scheduling.md",
          "quote": "仅当 counted=true 时 inflight 减一，并设置 counted=false"
        },
        {
          "path": "knowledge/algorithms/async-scheduling.md",
          "quote": "建立代次(r,g+1)，使其进入 WAIT_SLOT"
        }
      ]
    },
    "cost": {
      "assessment": "sufficient",
      "reason": "六类成本进入同一候选的资源账，启动周期下界注明设备服务、主机并行和共享字节口径；容量按物理并集与最后使用生存期计算。H 与 H_host 单位已区分，逻辑取消与物理回收延迟分别定义。独立复算得到串行时间 11、理想周期 8、吞吐倍率 1.375，以及两个池合计 34 MiB。原 COST-001 已关闭。",
      "evidence": [
        {
          "path": "knowledge/algorithms/async-scheduling.md",
          "quote": "C、G、O 和提交/释放开销 H 均以每单位独立工作的时间计。H_host 是无量纲的有效主机并行度"
        },
        {
          "path": "knowledge/algorithms/async-scheduling.md",
          "quote": "Q_j 是同一工作单位在共享资源 j 上累计承担的字节，B_j 是相同并发条件下的可持续字节/时间。"
        },
        {
          "path": "knowledge/algorithms/async-scheduling.md",
          "quote": "逻辑响应为 t_log−t_arr。自 t_log 起，本算法禁止新的业务提交与后继调度；无需等待设备排空。"
        }
      ]
    },
    "adaptation": {
      "assessment": "sufficient",
      "reason": "条件变化表把设备饱和、短请求、KV 压力、取消率、图重放、异构不平衡和共享地址分别连接到保留约束、调整候选和反转信号。提前推进被明确列为需要暂定边界及回滚协议的扩展，没有把本章保守算法的正确性外推到该扩展。",
      "evidence": [
        {
          "path": "knowledge/algorithms/async-scheduling.md",
          "quote": "| 长上下文或 KV 紧张 | 最后使用前不能回收 | 减少在途、拆开不同生存期的池 | 新缓冲挤出 KV，准入与有效完成率下降 |"
        },
        {
          "path": "knowledge/algorithms/async-scheduling.md",
          "quote": "若引入前者，取消、拒绝和回滚都必须作用于暂定边界，不能把安排计数解释成设备完成。"
        }
      ]
    },
    "diagnosis": {
      "assessment": "sufficient",
      "reason": "竞争解释各有可区分预测、干预和反证后的修正。检查具有独立请求前缀参考、账务与责任不变量，以及实际被检出的六种故意缺陷；没有以进程退出成功代替机制判断。CPU 协议验证与设备可见性、重叠和性能的边界明确。",
      "evidence": [
        {
          "path": "knowledge/algorithms/async-scheduling.md",
          "quote": "| 取消控制路径阻塞 | 设备未排空前本可抑制输出，却迟迟没有 t_log | 单独延迟通知处理与设备完成，比较 t_log、t_last | t_log 已及时而 t_free 晚，应转查物理责任 |"
        },
        {
          "path": "knowledge/algorithms/async-scheduling.md",
          "quote": "独立参考从完整 token 前缀直接计算玩具模型的串行输出，不使用调度器的 KV/代次状态"
        },
        {
          "path": "knowledge/algorithms/async-scheduling.md",
          "quote": "每个对照都必须被独立预期或不变量检出，不能仅打印预先写好的 PASS。"
        }
      ]
    }
  },
  "findings": [],
  "limitations": [
    "验收限于所声明的保守调度协议。检查未证明真实 CUDA/DMA、图重放、异构归约、编译后访问、同步作用域或性能，也未证明知识改善 Agent 的实际构建效果。",
    "脚本以槽单位表示暂存预留，以三层布尔值表示生产有效性；没有真实 KV 页、COW、完整缓存命中恢复、随机采样分布或逐层张量计算。完整前缀参考验证输出路由和推进，不能证明真实 KV 内容正确。",
    "脚本中的错误完成按终态处理；未模拟错误后仍有物理访问、部分入队或无法取得排空证据的隔离路径。正文对这些路径的安全性依赖真实结束证据，该条件仍需接口实现与设备验证。",
    "逐层模型契约所委托的 iteration-batching.md 仅提供部分摘录，position-mask-cache.md 未提供正文；本轮确认委托位置与全层完成要求，没有声称完整复核这两份链接目标。",
    "allocator 的核心主张可由完整来源说明支持；当前提供的原文摘录未包含 §11，不能据此独立核验完整 allocator 规则。vLLM 仅核对作者整理的机制说明，未读取源码归档。",
    "当前工具未提供文件读取或 Python 执行能力，资源与资源模板枚举均为空；未进行本地文件哈希重算、链接存在性检查或 Python 独立重跑。绑定哈希和执行结果分别取自本轮提供的材料与 actual_preflight。"
  ],
